package com.autoops.ai.validation;import com.autoops.ai.dto.AIOperation;import org.springframework.stereotype.Service;import java.util.Set;@Service public class AIOperationValidator{private static final Set<String>ALLOWED=Set.of("ADD_NODE","UPDATE_NODE","DELETE_NODE","ADD_EDGE","DELETE_EDGE","PROPOSE_COMMAND");public void validate(AIOperation op){if(op==null||!ALLOWED.contains(op.type()))throw new IllegalArgumentException("Unsupported AI operation");if(op.payload()==null)throw new IllegalArgumentException("AI operation payload required");}}
